// Author: MiYu. Source coupling creates replacement units with proportional life, real placement and population transfer.
#include "session.h"
#include "order_ids.h"
#include <algorithm>
#include <bit>
#include <cmath>

namespace war3 {
namespace {
float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
}
void ScriptSession::couplingInfo(SpellInfo& s){
    auto& data=definitions();auto type=[&](const char* key){auto value=data.field(s.ability,"AbilityData",std::string(key)+std::to_string(s.level));if(value.size()!=4 || !data.contains(ObjectData::code(value)))throw std::runtime_error("Coupling requires valid source unit types");auto id=ObjectData::code(value);if(data.property(id,"ubdg","0")=="1")throw std::runtime_error("Structure coupling is not implemented");return id;};
    if(s.kind==SpellKind::Decouple){s.splitTypes={type("DataA"),type("DataB")};if(s.area==-1)s.area=0;return;}s.helperType=type("DataA");s.resultType=type("UnitID");if(s.kind==SpellKind::CoupleInstant){float move=data.number(s.ability,"AbilityData","DataB"+std::to_string(s.level));if(move!=0 && move!=1)throw std::runtime_error("Couple Instant move-to-partner flag is not boolean");s.coupleMove=move!=0;}else s.coupleMove=true;
}
bool ScriptSession::coupleTarget(const UnitState& caster,const UnitState& target,const SpellInfo& s,bool visibility){
    if(caster.handle==target.handle || caster.owner!=target.owner || target.type!=s.helperType || caster.hero || target.hero || caster.building || target.building || caster.illusion || target.illusion || caster.removing || target.removing || caster.hidden() || target.hidden() || number(caster.life)<=0 || number(target.life)<=0 || target.paused || target.abilitiesDisabled() || caster.formTransition || target.formTransition || !caster.cargo.empty() || !target.cargo.empty() || caster.transport || target.transport)return false;
    if(auto found=coupleClaims_.find(caster.handle);found!=coupleClaims_.end() && found->second.first!=caster.handle)return false;if(auto found=coupleClaims_.find(target.handle);found!=coupleClaims_.end() && found->second.first!=caster.handle)return false;return !visibility || unitVisibleTo(target.handle,caster.owner);
}
std::uint32_t ScriptSession::couplePartner(const UnitState& caster,const SpellInfo& s){
    float nearest=s.area;std::uint32_t found=0;for(auto& [id,u]:units_)if(coupleTarget(caster,*u,s,true)){float distance=std::hypot(number(u->x)-number(caster.x),number(u->y)-number(caster.y));if(distance<nearest || (distance==nearest && (!found || id<found))){nearest=distance;found=id;}}return found;
}
bool ScriptSession::prepareCoupling(UnitState& unit,SpellInfo& s,std::uint32_t& target,SpellTargeting& targeting){
    if(s.kind==SpellKind::Decouple)return targeting==SpellTargeting::None && !unit.hero && !unit.building && unit.cargo.empty() && !unit.formTransition && !couplingPlacement(unit,{s.splitTypes[0],s.splitTypes[1]},{unit.handle}).empty();if(s.kind!=SpellKind::Couple && s.kind!=SpellKind::CoupleInstant)return true;if(targeting==SpellTargeting::None && s.kind==SpellKind::CoupleInstant)target=couplePartner(unit,s);if(!target || !alive(target,NativeKind::Unit) || !coupleTarget(unit,*units_.at(target),s,true))return false;targeting=s.targeting=SpellTargeting::Unit;if(s.kind==SpellKind::CoupleInstant && !s.coupleMove)s.unlimitedRange=true;return true;
}
bool ScriptSession::claimCouple(std::uint32_t id,const CastOrder& cast){
    if(cast.spell.kind!=SpellKind::Couple && cast.spell.kind!=SpellKind::CoupleInstant)return true;if(!alive(id,NativeKind::Unit) || !alive(cast.target,NativeKind::Unit) || !coupleTarget(*units_.at(id),*units_.at(cast.target),cast.spell,true))return false;coupleClaims_[cast.target]={id,cast.ticket};return true;
}
void ScriptSession::releaseCouple(const CastOrder& cast){
    auto found=coupleClaims_.find(cast.target);if(found!=coupleClaims_.end() && found->second==std::pair{cast.caster,cast.ticket})coupleClaims_.erase(found);
}
bool ScriptSession::smartCouple(std::uint32_t id,std::uint32_t target){
    if(!alive(id,NativeKind::Unit) || !alive(target,NativeKind::Unit))return false;auto u=units_.at(id);for(auto [ability,level]:u->abilities)if(level>0){auto& s=spellInfo(ability,unsigned(level));if((s.kind==SpellKind::Couple || s.kind==SpellKind::CoupleInstant) && coupleTarget(*u,*units_.at(target),s,true) && spellRequirements(u->owner,s) && beginSpell(id,ability,target,{},SpellTargeting::Unit,false,851971))return true;}return false;
}
std::vector<WorldPoint> ScriptSession::couplingPlacement(const UnitState& caster,const std::vector<std::uint32_t>& types,const std::vector<std::uint32_t>& ignore){
    struct Slot {WorldPoint point;float radius;bool flying;};std::vector<Slot> slots;std::vector<WorldPoint> points;auto& data=definitions();for(auto type:types){float radius=std::clamp(data.number(type,"UnitBalance","collision",16),0.f,512.f);bool flying=data.property(type,"umvt",data.field(type,"UnitData","movetp"))=="fly";bool placed=false;
        for(unsigned ring=0;ring<=16 && !placed;++ring)for(unsigned side=0;side<(ring?32u:1u);++side){float angle=float(side)*6.28318530718f/32;auto point=requireWorld().clamp({real(number(caster.x)+std::cos(angle)*ring*32),real(number(caster.y)+std::sin(angle)*ring*32)});auto path=requireWorld().route(point,point,radius,flying);if(path.empty() || std::hypot(number(path.back().x)-number(point.x),number(path.back().y)-number(point.y))>1)continue;bool free=true;for(auto& [id,u]:units_)if(std::find(ignore.begin(),ignore.end(),id)==ignore.end() && !u->removing && !u->hidden() && u->pathing && number(u->life)>0 && u->airborne()==flying && std::hypot(number(u->x)-number(point.x),number(u->y)-number(point.y))<u->collision+radius){free=false;break;}if(!free)continue;for(auto& slot:slots)if(slot.flying==flying && std::hypot(number(slot.point.x)-number(point.x),number(slot.point.y)-number(point.y))<slot.radius+radius){free=false;break;}if(!free)continue;slots.push_back({point,radius,flying});points.push_back(point);placed=true;break;}if(!placed)return {};
    }return points;
}
void ScriptSession::couplingCooldown(UnitState& unit,const SpellInfo& source){for(auto [ability,level]:unit.abilities)if(level>0 && couplingSpell(spellInfo(ability,unsigned(level)).kind))unit.spellCooldowns[ability]=simulationTime_+source.cooldown;}
void ScriptSession::replaceCouplingUnits(const std::vector<std::uint32_t>& before,const std::vector<std::uint32_t>& after){
    std::map<unsigned,std::pair<int,int>> changes;for(auto id:before)if(alive(id,NativeKind::Unit)){auto u=units_.at(id);if(u->foodCounted){changes[u->owner].first-=u->foodUsed;changes[u->owner].second-=u->foodMade;u->foodCounted=false;}}for(auto id:before)if(alive(id,NativeKind::Unit))removeUnit(id);for(auto id:after)if(alive(id,NativeKind::Unit)){auto u=units_.at(id);if(!u->removing && number(u->life)>0 && u->useFood && !u->illusion){u->foodCounted=true;changes[u->owner].first+=u->foodUsed;changes[u->owner].second+=u->foodMade;}}for(auto [owner,change]:changes)if(change.first || change.second)adjustFood(owner,change.first,change.second);
}
void ScriptSession::coupleEffect(std::uint32_t id,const CastOrder& cast){
    if(cast.spell.kind==SpellKind::Decouple){decoupleEffect(id,cast);return;}if(!alive(id,NativeKind::Unit) || !alive(cast.target,NativeKind::Unit))return;auto u=units_.at(id),partner=units_.at(cast.target);auto death=u->deathRevision,ownership=u->ownerRevision,otherDeath=partner->deathRevision,otherOwner=partner->ownerRevision;auto active=[&]{return alive(id,NativeKind::Unit) && alive(cast.target,NativeKind::Unit) && u->cast && u->cast->ticket==cast.ticket && u->deathRevision==death && u->ownerRevision==ownership && partner->deathRevision==otherDeath && partner->ownerRevision==otherOwner && u->owner==cast.owner && coupleTarget(*u,*partner,cast.spell,false);};if(!active() || !cancelCombat(*partner) || !active())return;partner->route.clear();partner->waypoint=0;partner->currentOrder=0;
    for(auto input:{id,cast.target}){auto held=units_.at(input)->inventory;for(auto item:held){if(!active())return;if(item && alive(item,NativeKind::Item) && items_.at(item)->holder==input)dropItem(input,item);}}if(!active())return;auto points=couplingPlacement(*u,{cast.spell.resultType},{id,cast.target});if(points.empty())return;auto life=u->life.add(partner->life),maximum=u->maxLife.add(partner->maxLife);bool selected=u->selected || partner->selected;auto result=createUnit(cast.owner,cast.spell.resultType,points[0].x,points[0].y,u->facing,0,nullptr,false);if(!alive(result.bits,NativeKind::Unit))return;auto replacement=units_.at(result.bits);replacement->life=real(std::clamp(number(life.divide(maximum).multiply(replacement->maxLife)),0.f,number(replacement->maxLife)));couplingCooldown(*replacement,cast.spell);if(!active()){removeUnit(result.bits);return;}finishCast(id,cast.ticket);
    if(!alive(id,NativeKind::Unit) || !alive(cast.target,NativeKind::Unit) || u->removing || partner->removing || number(u->life)<=0 || number(partner->life)<=0 || u->deathRevision!=death || u->ownerRevision!=ownership || partner->deathRevision!=otherDeath || partner->ownerRevision!=otherOwner || u->owner!=cast.owner || partner->owner!=cast.owner){removeUnit(result.bits);return;}replaceCouplingUnits({id,cast.target},{result.bits});if(selected && cast.owner==localPlayer_.value_or(0) && alive(result.bits,NativeKind::Unit) && !replacement->removing && number(replacement->life)>0 && replacement->owner==cast.owner)selectUnit(result.bits,true);
}
void ScriptSession::decoupleEffect(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);auto death=u->deathRevision,ownership=u->ownerRevision;auto active=[&]{return alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->owner==cast.owner && u->deathRevision==death && u->ownerRevision==ownership && u->cast && u->cast->ticket==cast.ticket;};if(!active())return;auto points=couplingPlacement(*u,{cast.spell.splitTypes[0],cast.spell.splitTypes[1]},{id});if(points.size()!=2)return;auto held=u->inventory;for(auto item:held){if(!active())return;if(item && alive(item,NativeKind::Item) && items_.at(item)->holder==id)dropItem(id,item);}if(!active())return;bool selected=u->selected;std::vector<std::uint32_t> results;
    for(unsigned i=0;i<2;++i){auto result=createUnit(cast.owner,cast.spell.splitTypes[i],points[i].x,points[i].y,u->facing,0,nullptr,false);if(!alive(result.bits,NativeKind::Unit) || !active()){if(alive(result.bits,NativeKind::Unit))removeUnit(result.bits);for(auto other:results)removeUnit(other);return;}auto replacement=units_.at(result.bits);replacement->life=real(std::clamp(number(u->life.multiply(replacement->maxLife.divide(u->maxLife))),0.f,number(replacement->maxLife)));couplingCooldown(*replacement,cast.spell);results.push_back(result.bits);}finishCast(id,cast.ticket);if(!alive(id,NativeKind::Unit) || u->removing || number(u->life)<=0 || u->owner!=cast.owner || u->deathRevision!=death || u->ownerRevision!=ownership){for(auto other:results)removeUnit(other);return;}replaceCouplingUnits({id},results);if(selected && cast.owner==localPlayer_.value_or(0))for(auto result:results)if(alive(result,NativeKind::Unit) && !units_.at(result)->removing && number(units_.at(result)->life)>0 && units_.at(result)->owner==cast.owner)selectUnit(result,true);
}
}
